T["Der Markt nutzt Preise aus dem AH-Addon Midas. Sobald du oder jemand aus der Gilde mit Midas im AH scannt, schaltet sich diese Seite frei."] = "市场使用拍卖插件Midas的价格。只要你或公会中有人用Midas扫描拍卖行，此页面就会解锁。"
