T["Der Rand des Oasis-Fensters leuchtet in deiner Farbe"] = "Oasis窗口边框以你的颜色发光"
T["Der Ring zeigt, wer ohne offene Punkte ist."] = "圆环显示谁没有未分配的点数。"
