T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "聊天输入框被Oasis使用过（例如“密语”按钮），之后输入了/cast命令。"
