T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "地下城地图没有坐标。点击这里，然后点击地图上你当前所在的位置。在两个相距较远的位置完成后，Oasis会在地图上显示你和你的队伍 - 对整个公会可见。"
T["Die Gilde bekommt Bescheid"] = "公会会收到通知"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "公会会看到你在回复谁。默认：关"
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "公会会在地图上看到你的篝火%d分钟。"
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "公会会在编年史中看到你的成就"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "公会目前没有在找此地下城的东西。"
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "公会尚未分配战利品点数 - 团队领导开始团队副本后会显示你的数值。"
T["Die Gildenbank wurde noch nicht gelesen"] = "尚未读取公会银行"
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "公会管理在王冠 > 模块 > 团队与战利品中指定团队领袖和助理（名字或按公会会阶）。进行中的团队副本中，团队领袖和助理也算。"
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "公会管理在王冠 > 模块 > 团队与战利品中指定团队领袖。进行中的团队副本中，团队领袖和助理也算。"
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "公会管理在王冠 > 模块 > 团队与战利品中指定团队领袖。进行中的团队副本中，团队领袖也算。"
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "公会管理只允许更高会阶创建组队招募。"
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "公会管理只允许更高会阶创建投票。"
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "公会管理已关闭寻找伙伴功能。"
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "公会管理已关闭公开邀请 - 请直接挑战某人。"
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "公会管理在王冠 > 模块中设定哪些会阶有此权限。"
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "魔兽的公会查找器可帮助寻找 - 中立，无广告。"
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "上限只能由会长设定。会阶1 = 会长。"
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "按钮会将命令写入聊天栏 - 按回车后才执行。"
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "这些快捷键也在魔兽按键设置的插件 > Oasis中。Esc关闭Oasis窗口（战斗中不行 - 那时Esc归游戏使用）。"
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "这些快捷键也在魔兽按键设置的插件 > Oasis中。只要你最后点击过Oasis窗口，Esc就会关闭它。"
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "工具栏会向上收起；将鼠标移到屏幕顶部边缘它会下来（仅在顶部停靠时）"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "预定行仅在你处于队伍或团队中时显示"
T["Die Waechter der Sande"] = "流沙守望者"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "打开了世界地图。北边在哪来着？"
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "顶部的真实工具栏会立即显示每项更改"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "前20点耐力每点提供1生命值，之后每点提供10生命值。"
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "公会中跑尸次数最多。墓地有一张刻着你名字的长椅。"
T["Die meisten Screenshots der Gilde"] = "公会中截图最多"
T["Die meisten Tode der letzten 7 Tage"] = "最近7天死亡最多"
T["Die meisten vollen Taschen der Gilde"] = "公会中背包满最多次"
T["Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "最新公告在概览顶部显示3天。"
T["Die vergessenen Teiche"] = "遗忘之池"
T["Diese Abzeichen zeigt deine Profilkarte zuerst - bei dir und bei der Gilde."] = "这些徽章会优先显示在你的资料卡上 - 对你和公会都是。"
T["Diese Hinweise ausschalten"] = "关闭这些提示"
