T["Diese Sitzung: %d EP in %s"] = "本次会话：%d经验（用时%s）"
T["Diese Sprache gilt nach dem naechsten /reload - hier klicken zum Neuladen."] = "该语言将在下次/reload后生效 - 点击此处重载。"
