T["Dieser Client meldet keine seltenen Gegner (Schnittstelle fehlt). /oa probe rares zeigt Details."] = "此客户端不报告稀有敌人（缺少接口）。/oa probe rares显示详情。"
T["Dir fehlt nichts, was die Gilde hat - stark!"] = "公会有的你都不缺 - 厉害！"
T["Dir selbst etwas zugefluestert. Wer sonst hoert dir so gut zu?"] = "给自己发了密语。还有谁会这么认真听你说话？"
