T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "还没有里程碑。升级、学专业 - 你的故事从这里开始。"
T["Noch keine Meldungen aus der Gilde."] = "还没有来自公会的报告。"
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "还没有精彩瞬间 - 尽管玩吧，Oasis会记录。"
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "官员聊天中还没有消息。从现在起在/o频道写的所有内容都会显示在这里。"
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "还没有位置 - 一旦有Oasis的成员在外活动，地图就会填满。"
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "还没有价格。一旦有人用Midas扫描拍卖行，就会显示在这里。"
T["Noch keine Profile gespeichert."] = "还没有保存的配置。"
