T["Noch keine Regeln"] = "还没有规则"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "还没有规则。选择一个快速模板或在上方创建自己的规则。"
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "还没有声望数据。一旦有Oasis的成员在线就会自动获取。"
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "还没有共享收藏。一旦有Oasis的公会成员在线，就会显示在这里。"
T["Noch keine Sets."] = "还没有套装。"
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "还没有发现。一旦有Oasis用户看到稀有敌人，就会显示在这里。"
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "还不知道游戏时间。Oasis会在你每晚在线时学习 - 并采用其他人的资料。"
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "还没有搜索。输入等级并点击\"搜索\" - 有公会的玩家会被隐藏。"
T["Noch keine Taktiken."] = "还没有战术。"
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "还没有战术。团队领导可以为每个首领创建简短战术 - 所有人都能在这里看到，选中首领时也会显示。"
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "还不知道天赋。Oasis成员会自动共享；其他玩家：选中并观察（右键 > 观察）或选中目标后重新打开此处。"
