T["Wer"] = "谁"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "发送了被其他人拒绝的数据的人（无权限、伪造来源、虚构条目）。未修改的Oasis几乎不会这样 - 这只是提示，不是证据。"
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "表示兴趣的人会出现在这里合适的位置。活动确定后，直接在卡片上报名。"
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "公会中谁的愿望单上有此物品"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "谁能在导航中看到此模块（公会管理始终能看到全部）"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "离开公会或被移除的人。如有人回来，Oasis会通知公会管理。"
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "谁能看到顶部的王冠。无权限时王冠为灰色，只打开预览。"
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "谁可以在公会聊天顶部置顶消息"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "尚不知道谁有邀请权限 - 用你的大号登录一次，Oasis会记住公会管理。"
T["Wer geht mit nach %s? Ich suche %s"] = "谁一起去%s？我在找%s"
T["Wer hat ...?"] = "谁有……？"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "谁有你需要的任务物品？你又能帮谁？"
T["Wer hat was bekommen"] = "谁得到了什么"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "谁可以在团队中记录点数（出勤/战利品）。"
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "队伍或团队中谁有哪些增益 - 还缺什么"
T["Wer ist bereit? Ampeln je Spieler"] = "谁已就绪？每位玩家的状态灯"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "本周谁已锁定，谁空闲且已解锁 - 大号和小号"
T["Wer ist online"] = "谁在线"
T["Wer ist online?"] = "谁在线？"
T["Wer ist wann online"] = "谁在什么时间在线"
T["Wer ist wie weit"] = "谁进度如何"
T["Wer kann was herstellen, Markt, Gildenbank"] = "谁能制作什么、市场、公会银行"
T["Wer koennte mit: %s"] = "可能同去的：%s"
T["Wer koennte mit?"] = "谁可能同去？"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "经常参加且获得较少的人在“需求”时优先。每周会衰减一部分点数。"
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "以合适职责报名的人会立即被邀请到你的队伍。"
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "谁在哪个阵营的什么声望？即将达成、一起刷、本周进度"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "谁输出最多、治疗最多、承受最多？"
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "公会管理成员由会长在王冠 > 公会中设定。"
T["Werbung"] = "招募"
T["Werte"] = "属性"
T["Werte bringen deiner Rolle nichts"] = "这些属性对你的职责无用"
T["Werte nur zur Info"] = "属性仅供参考"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "你角色的属性、年鉴、每日目标、纪录和冒险。"
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "属性：+治疗、智力、精神、法力回复;武器：法杖或单手武器 + 带治疗的副手;治疗：预先回春术和愈合，大伤害用治疗之触;提示：用激活回蓝，用复生救倒下的治疗"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "属性：+治疗、智力、法术暴击（启迪返还法力）、法力回复;武器：单手武器 + 带治疗的副手/盾牌;治疗：小伤害用圣光闪现，大伤害用圣光术（低级）;提示：分发祝福，被攻击时用圣佑术"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "属性：+治疗、法力回复（MP5）、智力 - 精神作用不大;武器：单手武器 + 带治疗的盾牌;治疗：团队用治疗链，坦克用治疗波（低级）;提示：放置法力之泉图腾，给坦克上大地之盾"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "属性：+治疗、精神（冥想：施法时也回复）、智力、法力回复;武器：法杖或单手武器 + 带治疗的副手、魔杖;治疗：预先恢复和真言术：盾，坦克用强效治疗术（低级）;提示：队伍用治疗祷言，仇恨过高时用渐隐术"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "属性：护甲（熊形态大幅提升）、耐力、敏捷（躲闪 + 护甲）;武器：对伤害无影响 - 只看属性（带耐力的法杖/长柄武器）;循环：槌击、挥击打群体、挫志咆哮;提示：力量增加威胁，开场用激怒"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "属性：力量（1点 = 2攻击强度）、敏捷（攻击强度 + 暴击）、暴击、命中至+9 %;武器：对伤害无影响 - 只看属性;循环：爪击/撕碎攒连击点，然后凶猛撕咬;提示：用变形重置（重新变形）回能量，从潜行中突袭"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "属性：力量（1点 = 2攻击强度）、暴击（触发乱舞 = 攻速更快）、命中至+9 %;武器：慢速双手武器 - 风怒按每次攻击触发，越慢伤害越高;循环：风怒武器、风暴打击、地震术;提示：为队伍放置大地之力图腾和风怒图腾"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "属性：力量（1点 = 2攻击强度）、暴击、命中至+9 %;武器：慢速双手武器 - 圣印和审判按每次攻击生效;循环：正义圣印/命令圣印、审判、重新施放圣印;提示：法力充足时才用奉献，给自己上力量祝福"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "属性：命中至+9 %、敏捷（1攻击强度，约29 = 1 %暴击）、攻击强度、暴击;武器：战斗 = 快速副手、慢速主手（邪恶攻击）; 刺杀用匕首;循环：攒连击点、保持切割、然后剔骨;提示：双持时普通攻击更容易未命中 - 命中最重要"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "属性：命中至+9 %、敏捷（2远程攻击强度，约53 = 1 %暴击）、攻击强度、智力;武器：慢速远程武器（每发伤害高）、带属性的近战武器;循环：猎人印记、自动射击、穿插瞄准射击/多重射击;提示：喂养宠物并保持快乐，冰冻陷阱（方块）用于控制"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "属性：命中至+9 %、力量（1点 = 2攻击强度）、暴击（约20敏捷 = 1 %）;武器：慢速双手武器（致死打击、英勇打击按每次攻击生效）;循环：积攒怒气、致死打击/嗜血、旋风斩、多余怒气用英勇打击;提示：战前用战斗怒吼，20 %血量以下用斩杀"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "属性：防御（60级440防御免疫首领暴击）、耐力、护甲、盾牌格挡;武器：单手武器 + 盾牌，快速武器 = 更多怒气;循环：盾牌猛击/复仇、对目标破甲、怒气多时用英勇打击;提示：命中有助于嘲讽和技能不被未命中"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "属性：防御、耐力、护甲，然后法术伤害以提高威胁;武器：单手武器（最好带法术伤害）+ 盾牌;循环：开启正义之怒、群体用奉献、保持神圣之盾;提示：法力紧张 - 带上智慧圣印或智力"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "属性：法术伤害、法术暴击（元素集中节省法力）、智力、法力回复;武器：单手武器 + 带法术伤害的盾牌/副手;循环：狂按闪电箭、群体用闪电链、烈焰震击;提示：团队中法术命中至+16 %，用法力之泉图腾防止空蓝"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "属性：法术伤害、法术暴击、智力、团队中法术命中至+16 %;武器：法杖或单手武器 + 带法术伤害的副手;循环：月火术 + 虫群，然后愤怒或星火术;提示：法力紧张时给自己用激活"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "属性：法术伤害、法术命中至+16 %（团队）、耐力、智力;武器：法杖或匕首 + 带法术伤害的副手，魔杖用于剩余法力;循环：腐蚀术 + 诅咒，然后暗影箭; 用生命分流代替喝水;提示：耐力有双重收益（生命分流、虚空行者/灵魂链接）"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "属性：法术伤害、法术命中至+16 %（团队）、精神回法力;武器：法杖或单手武器 + 带法术伤害的副手;循环：暗言术：痛、心灵震爆、精神鞭笞;提示：保持暗影形态，吸血鬼的拥抱治疗队伍"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "属性：法术伤害，然后法术命中至+16 %（团队首领）、智力、法术暴击;武器：带法术伤害的法杖，加一根魔杖用于剩余法力;循环：狂按寒冰箭或火球术，空蓝时用唤醒;升级：智力和精神 = 更少休息，组队时用变羊（月亮）"
