T["Zeigt BESSER / SCHLECHTER / NICHT TRAGBAR mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "显示更好/更差/无法穿戴及影响（DPS、生命值、护甲）和属性表。暴雪的比较需按Shift才显示。如已加载自带比较的nesUI，Oasis不显示（否则重复）- 可在那里用/nes vergleich关闭。"
