T["1 Upgrade"] = "1 件提升"
T["1.  Kampflog mitschreiben lassen (Einstellungen > Bereiche > Kampf-Rangliste, steht auf an).\n2.  Nach dem Spielen im Oasis-Ordner ImportCrits.bat doppelklicken.\n3.  Im Spiel /reload - dein hoechster Crit steht hier und wird mit der Gilde geteilt."] = "1.  保持战斗日志开启（设置 > 模块 > 战斗排行榜，默认开启）。\n2.  游戏结束后，双击 Oasis 文件夹中的 ImportCrits.bat。\n3.  在游戏中 /reload - 你的最高暴击会显示在这里并与公会共享。"
T["1. Ueberschrift"] = "1. 标题"
T["2 Min"] = "2 分钟"
T["2. Nachricht"] = "2. 消息"
T["3D-Modell"] = "3D 模型"
T["5 Min"] = "5 分钟"
T["Abend-Check"] = "开团检查"
T["Aktionen"] = "操作"
T["Aktiv: Meme-Sounds, Musik und Gilden-Emojis sind enthalten."] = "已启用：包含梗音效、音乐和公会表情。"
T["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "官员会阶以下的活跃成员在同一会阶停留这么多天后，会出现在“晋升”列表中。0 = 关闭。"
T["Aktuelles Gebiet zuerst"] = "当前区域优先"
T["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "所有模块按主题分组：公会、一起玩、团队、交易、娱乐。点击标题可折叠该组。"
T["Alle Gebiete aufklappen"] = "展开所有区域"
T["Alle Gebiete zuklappen"] = "折叠所有区域"
T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "所有成员及其会阶、等级和 Oasis 版本。右键点击一行：更改会阶。"
T["Alle Schriften unter der SIL Open Font License 1.1"] = "所有字体均采用 SIL Open Font License 1.1"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: 燃烧刺激：立刻跑出团队（你马上就会死）。\nAll: 开场资源全满 - 全力输出。\nTank: 安排坦克顺序（燃烧刺激会点坦克）。\nDD: 不要站在龙的正面或背后。"
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: 不要让 8 个火誓者死在团队附近（爆炸）。\nTank: 每个小怪坦克把自己的火誓者拉开，术士放逐。\nHealer: 驱散，留意小怪坦克。\nDD: 先打加尔，小怪听指挥再打。"
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: 把两只熔火怒犬拉离首领坦住，不要击杀。\nTank: 熔岩飞溅叠得太高时更换古雷曼格坦克。\nDD: 只打古雷曼格。"
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: 先杀 4 个牧师，它们会互相治疗。\nTank: 把萨弗隆和牧师分开。\nDD: 打断！阻止牧师的黑暗治愈。"
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: 火焰抗性！拉格纳罗斯之怒会击退近战 - 之后再回去。\nAll: 烈焰之子阶段（3 分钟后或他下潜时）：击杀所有烈焰之子。\nTank: 第二坦克随时准备接手被击飞的主坦克。\nHealer: 分散站位，远程不要靠太近（熔岩爆裂）。\nDD: 近战：控制好法力，远程保持距离。"
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 烈焰打击会叠加 - 远程躲到柱子后消层。\nTank: 两个坦克躲在柱子后，龙翼打击会击退。\nDD: 必须装备奥妮克希亚鳞片披风。"
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: 立刻解除基赫纳斯的诅咒（治疗效果降低）。\nAll: 离开火焰之雨。\nTank: 把两个烈焰行者分开坦。\nDD: 先杀烈焰行者，再打基赫纳斯。"
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: 立刻解除鲁西弗隆的诅咒和末日降临（法师/德鲁伊、牧师/圣骑士）。\nTank: 把两个护卫分开坦 - 小心精神控制！\nHealer: 分散站位，驱散被精神控制的玩家。\nDD: 先杀护卫，再打鲁西弗隆。"
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: 活体炸弹：立刻跑出团队！\nAll: 地狱火 - 远离首领，驱散点燃法力。\nTank: 守住中间，地狱火时短暂离开。\nDD: 地狱火时近战后撤。"
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: 注意护卫的魔法反射/伤害护盾 - 此时停止输出。\nTank: 每个坦克一个护卫，法师变羊精英护卫。\nDD: 先杀治疗护卫（Flamewaker Healer）。"
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: 绝不要站在奥妮克希亚的正面或背后（吐息和扫尾）。\nAll: 第 2 阶段（65%）：躲开火球，不要进入洞穴入口。\nAll: 第 3 阶段（40%）：恐惧 - 准备好防护恐惧结界/战栗图腾，避开熔岩裂缝。\nTank: 把奥妮克希亚侧向贴墙，头部背对团队。\nTank: 第 2 阶段：收拢雏龙。第 3 阶段：立刻拉回仇恨。\nHealer: 坦克优先，第 2 阶段分散站位。\nDD: 等坦克攻击 3 次再打。第 2 阶段：先杀雏龙。"
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: 恐慌 - 防护恐惧结界/战栗图腾，猎人：狂暴时使用宁神射击。\nAll: 离开地上的熔岩火焰。\nTank: 让玛格曼达背对团队。\nDD: 远程在后方分散站位。"
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: 第 1 阶段：龙人从两侧出现，注意职业点名。\nAll: 第 3 阶段（20%）：骷髅再次复活 - 再杀一遍。\nTank: 把奈法利安拉到墙边，恐惧 - 防护恐惧结界。\nHealer: 牧师职业点名：治疗会造成伤害 - 小心。\nDD: 猎人/战士：注意职业点名（武器损坏、姿态）。"
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: 第 1 阶段：摧毁龙蛋（通过宝珠精神控制），接住小怪。\nAll: 龙蛋全毁后：首领进入房间 - 火焰新星。\nTank: 在楼梯处聚拢小怪。\nDD: 先杀法师和龙人。"
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 狂暴 - 猎人：宁神射击。\nTank: 两个坦克，注意龙翼打击。\nDD: 必须装备奥妮克希亚鳞片披风。"
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 埃博诺克之影会治疗首领 - 中了减益的坦克换坦。\nTank: 两个坦克在中埃博诺克之影时交换。\nDD: 必须装备奥妮克希亚鳞片披风。"
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: 击退 - 贴墙站位。\nTank: 两个坦克，击飞会分摊仇恨。\nDD: 坦克中致死打击：治疗做好准备。"
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: 他会传送 - 获得仇恨的人不要跑开。\nAll: 解除沙斯拉尔的诅咒，魔爆术：近战保持距离。\nTank: 每次闪现后立刻重新贴上。\nHealer: 驱散（衰减魔法）。"
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: 每周从五种吐息中出现两种 - 躲到拐角后规避吐息。\nAll: 用沙漏之沙解除青铜减益。\nTank: 在门口坦，团队站在拐角后。\nDD: 狂暴时使用宁神射击。"
T["Alt halten: alle Werte und Bewertung. Shift: Blizzard-Vergleich."] = "按住 Alt：全部属性和评分详情。Shift：暴雪对比。"
T["Alt loslassen: kompakter Vergleich. Shift: Blizzard-Vergleich."] = "松开 Alt：简洁对比。Shift：暴雪对比。"
T["Altes Oasis"] = "旧版 Oasis"
T["An: mit der Maus an eine eigene Stelle ziehen. Aus: haengt am Talentfenster."] = "开启：用鼠标拖到任意位置。关闭：停靠在天赋窗口旁。"
T["Anfuehrer der Dunkelspeere"] = "暗矛部族的领袖"
T["Angefangener Text bleibt beim Wechsel des Gespraechs stehen"] = "切换对话时保留未发送的文字"
T["Animationen aus"] = "关闭动画"
T["Ansprechpartner"] = "联系人"
T["Anwesenheit und Ausruestung der Gilde im Blick."] = "随时掌握出勤和公会装备情况。"
T["Auf dem Flug nichts erkennen oder melden"] = "飞行途中不检测也不报告"
T["Auf dem Flugmeister-Flug kannst du ohnehin nicht anhalten"] = "反正飞行途中你也停不下来"
T["Aus FojjiCore (%d)"] = "来自 FojjiCore (%d)"
T["Aus Guides zur Forever-Beta - kann sich noch aendern."] = "来自 Forever 测试版攻略 - 仍可能变动。"
T["Aus dem Soundpaket (ruhig)"] = "来自音效包（柔和）"
T["Aus: das Fenster verschwindet. Zurueck mit /oa builds."] = "关闭：窗口消失。使用 /oa builds 恢复。"
T["Ausfuehrliche Karten"] = "详细卡片"
T["Ausklappen"] = "展开"
T["Ausloggen: Blizzards Dialogliste war von Oasis beruehrt (ab 0.5.478 behoben - bitte Oasis aktualisieren)."] = "登出：暴雪的对话框列表被 Oasis 污染（0.5.478 已修复 - 请更新 Oasis）。"
T["Banner auf der Uebersicht: Midas, das Auktionshaus-Addon von Rebo aus der Gilde OASIS"] = "概览横幅：Midas，公会 OASIS 的 Rebo 制作的拍卖行插件"
T["Befoerderung vorschlagen nach"] = "建议晋升的天数"
T["Beim naechsten Wurf siehst du alt aus!"] = "下一把你就完了！"
T["Beispieldaten gibt es nur in der Entwicklerversion."] = "示例数据仅在开发者版本中提供。"
T["Bereiche freigeben"] = "开放模块"
T["Bereit fuer den Pull? Bereitschaft, Verzauberungen und Buffs je Spieler"] = "准备开怪了吗？每位玩家的就位状态、附魔和增益"
T["Bestaetigte Crit-Rekorde aus der Logdatei importiert."] = "已从日志文件导入确认的暴击纪录。"
T["Beta-Geschenk"] = "测试版礼物"
T["Beute automatisch verteilen, wenn du Pluendermeister bist"] = "你是战利品分配者时自动分配战利品"
T["Beuterat ab Rang"] = "拾取委员会起始会阶"
T["Bilder / Sek."] = "帧/秒"
T["Bilder ueber 1 ms (seit Sitzungsbeginn): %d"] = "超过 1 毫秒的帧（本次会话）：%d"
T["Bitte den Namen eines Gildenmitglieds eingeben (nicht einen eigenen Charakter)."] = "请输入一名公会成员的名字（不是你自己的角色）。"
T["Blockiert"] = "被阻止"
T["Blockierung von %s beobachtet; Ausloeser nicht bestaetigt."] = "观察到 %s 被阻止；原因尚未确认。"
T["Boss der Defias"] = "迪菲亚的首领"
T["Boss von Ratschet - alles hat seinen Preis"] = "棘齿城的老板 - 一切皆有价码"
T["Boss-Positionen im Dungeon-Atlas und Drop-Chancen der Dungeon-Bosse - GPL-2.0. Autoren: Lag, Daviesh und weitere"] = "地下城图集中的首领位置和地下城首领掉落率 - GPL-2.0。作者：Lag、Daviesh 等"
T["Bosse & Beute"] = "首领与战利品"
