T["Builds aus der Gilde ausgeblendet. Wieder einblenden: /oa builds"] = "公会天赋配置已隐藏。重新显示：/oa builds"
T["Builds aus der Gilde wird wieder neben dem Talentfenster gezeigt."] = "公会天赋配置重新显示在天赋窗口旁。"
