T["Casual: Hinweis"] = "Casual：提示"
T["Casual: Klick"] = "Casual：点击"
T["Casual: Schalter"] = "Casual：开关"
T["Charakterstatistik - hoechster Einzelwert, Crit-Status unbekannt"] = "角色统计 - 最高单次数值，暴击状态未知"
T["Chat-Eingabe und Zauberbefehle koennen beteiligt sein."] = "可能与聊天输入和施法命令有关。"
T["Chat-Eingabe und Zielwechsel koennen beteiligt sein."] = "可能与聊天输入和目标切换有关。"
T["Chatnachrichten erfordern in diesem Client eine direkte Eingabe."] = "此客户端中聊天消息需要直接输入。"
T["Credits"] = "鸣谢"
T["Crit-Heilung"] = "暴击治疗"
T["Crit-Import gehoert zu einem anderen Charakter."] = "暴击导入数据属于另一个角色。"
T["Crit-Quelle pruefen"] = "检查暴击来源"
T["Crit-Rekorde aus den Kampflog-Dateien uebernommen."] = "已从战斗日志文件导入暴击纪录。"
T["Crits beim Kampf allein automatisch zaehlen"] = "单独战斗时自动统计暴击"
