T["Das X am Fenster klappt Oasis in die Leiste ein. Das X an der Leiste schliesst ganz."] = "窗口上的 X 将 Oasis 收起到工具栏。工具栏上的 X 则完全关闭。"
T["Das gelbe Ausrufezeichen am Symbol zeigt das an."] = "图标上的黄色感叹号表示这一点。"
T["Das war nur Glueck! Nochmal!"] = "那只是运气！再来！"
T["Das war's schon. Den Rundgang findest du jederzeit wieder unter Einstellungen > Status oder mit /oa rundgang."] = "就这些了。随时可以在 设置 > 状态 中或用 /oa rundgang 重新打开导览。"
T["Daten"] = "数据"
T["Deckend"] = "不透明"
T["Dein Charakter"] = "你的角色"
T["Deine Stats: Oasis-Rang, Abzeichen und alle Zaehler"] = "你的数据：Oasis 等级、徽章和所有计数"
T["Den Download findest du im Discord der Gilde."] = "下载地址见公会的 Discord。"
T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "客户端不允许 Oasis 开启战斗日志 - 请自行输入 /combatlog。"
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "所选模块的内容。概览显示谁在线、即将进行的事项和最新动态。"
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "点击小地图按钮或输入 /oa 打开 Oasis。右上角的横线可将窗口变为窄工具栏。"
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "带历史记录的官员频道（/o）- 仅限拥有官员聊天权限的会阶。"
T["Der gelbe Strich links in der Liste zeigt das an."] = "列表左侧的黄色竖条表示这一点。"
