T["Noch kein positiver Einzelrekord gemeldet."] = "尚未上报有效的单次纪录。"
T["Noch keine Durchsagen. Schreib links die erste - Ueberschrift, Nachricht, senden."] = "暂无公告。在左侧写下第一条 - 标题、消息、发送。"
T["Noch keiner bestaetigt - der Twink traegt dich mit /oa twink als Main ein."] = "尚无确认 - 小号需用 /oa twink 将你登记为主号。"
