T["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "当晚已通过需求获得过物品的人，需求时排在所有未获得物品的人之后（同一掷骰档位）。"
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "为该活动预订了物品的人，需求时优先于其他所有人。"
T["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "队伍或团队中谁有哪些增益 - 以及谁能补上缺少的"
T["Wer ist in der Gilde, welcher Rang, wer hat altes Oasis."] = "谁在公会里、什么会阶、谁在用旧版 Oasis。"
