T["Wie die Schrift"] = "与文字相同"
T["Wieder am Talentfenster andocken"] = "重新停靠到天赋窗口"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "在队伍中 WoW 不会告诉插件是谁打出的命中。只有当暴击紧随你自身的攻击、且战斗后与伤害统计相符时，Oasis 才会计入。在排行榜中标记为估算。"
T["WoW-Klassiker"] = "WoW 经典"
T["Wochenaufgaben %d/%d"] = "每周任务 %d/%d"
T["World of Warcraft und zugehoerige Namen, Wappen und Grafiken sind Marken von Blizzard Entertainment. Oasis ist ein Fan-Projekt und steht in keiner Verbindung zu Blizzard."] = "World of Warcraft 及相关名称、徽记和图像均为 Blizzard Entertainment 的商标。Oasis 是玩家自制项目，与 Blizzard 无任何关联。"
T["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "掷骰：顺序为 需求 > 副天赋 > 幻化，然后比点数。分数：由战利品分数得出的优先级决定。拾取委员会：官员投票，战利品分配者发放。"
T["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "齿轮 = 设置（外观、音效、提示）。旁边是语言，以及公会管理层专用的皇冠。"
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "显示绿色、蓝色和史诗物品分解后可能获得的材料"
T["Zeigt in der Suche an, dass ihr per Sprache redet (Discord o.ae.). Beitreten regelt weiter Blizzard bzw. dein Gruppenleiter."] = "在招募列表中显示你们使用语音交流（Discord 等）。加入队伍仍由暴雪/你的队长处理。"
